package com.lexorion.workforce.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import lombok.Getter;import lombok.NoArgsConstructor;import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="organization_change_events",indexes=@Index(name="idx_org_change_workspace_time",columnList="workspace_id,occurred_at")) @Getter @NoArgsConstructor
public class OrganizationChangeEvent {@Id@UuidGenerator private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="workspace_id",nullable=false,updatable=false)private WorkforceWorkspace workspace;@Column(name="resource_type",nullable=false,length=32,updatable=false)private String resourceType;@Column(name="resource_key",nullable=false,length=63,updatable=false)private String resourceKey;@Column(nullable=false,length=48,updatable=false)private String action;@Column(name="previous_value",length=150,updatable=false)private String previousValue;@Column(name="new_value",length=150,updatable=false)private String newValue;@Column(name="occurred_at",nullable=false,updatable=false)private Instant occurredAt;public OrganizationChangeEvent(WorkforceWorkspace w,String type,String key,String action,String from,String to){workspace=w;resourceType=type;resourceKey=key;this.action=action;previousValue=from;newValue=to;occurredAt=Instant.now();}}
